mapper.select:

SELECT 
       CD                       /*코드*/ 
     , UCD                      /*상위코드*/ 
     , CD_CLS                   /*코드분류*/ 
     , CD_NM || CASE WHEN USE_YN = 'Y' THEN '' ELSE '【폐지】' END AS CD_NM /*코드명*/ 
     , CD_SHORT_NM              /*코드약칭*/ 
  FROM CMN_CODE 
 WHERE CD_CLS = #{CD_CLS}


  AND CD = #{CD} 


  AND UCD = #{UCD} 


  AND SYSDATE BETWEEN EFFT_STAT_DT AND EFFT_END_DT 


  AND USE_YN = #{USE_YN} 


  AND (   CD_NM LIKE  '%'||#{CD_NM}||'%' 
       OR CD  LIKE '%'||#{CD_NM}||'%'
       OR ENG_NM  LIKE '%'||#{CD_NM}||'%'                    
      )


  AND UNIT_SYSTEM_RCD = #{UNIT_SYSTEM_RCD} 


  AND CD = #{CD} 


  AND CD_PRP1 = #{CD_PRP1} 


  AND CD_PRP2 = #{CD_PRP2} 


  AND CD_PRP3 = #{CD_PRP3} 


  AND CD_PRP4 = #{CD_PRP4} 


  AND CD_PRP5 = #{CD_PRP5} 


  AND CD_PRP6 = #{CD_PRP6} 


  AND CD_PRP7 = #{CD_PRP7} 


  AND CD_PRP8 = #{CD_PRP8} 


  AND CD_PRP9 = #{CD_PRP9} 


  AND CD_PRP10 = #{CD_PRP10} 


  AND CD_PRP11 = #{CD_PRP11} 


  AND CD_PRP12 = #{CD_PRP12} 


  AND CD_PRP13 = #{CD_PRP13} 


  AND CD_PRP14 = #{CD_PRP14} 


  AND CD_PRP15 = #{CD_PRP15} 


  AND CD_PRP16 = #{CD_PRP16} 


  AND CD_PRP17 = #{CD_PRP17} 


  AND CD_PRP18 = #{CD_PRP18} 


  AND CD_PRP19 = #{CD_PRP19} 


  AND CD_PRP20 = #{CD_PRP20} 


  ORDER BY  ${ORDER_BY}
